    const long double stateCells=static_cast<long double>(total)*(2*n+m+nc)+options.islands*(4.L*n*n+4*n)+request.history_capacity*4.L;const long double working=static_cast<long double>(total)*(7*n+4*(m+nc))*sizeof(double)+options.islands*8.L*n*n*sizeof(double)+request.history_capacity*32;
    const auto stateMaximum=std::min<std::size_t>(64*1024*1024,options.maximumBytes/8);require(working+(options.checkpoint.empty()?0:stateCells*160)<options.maximumBytes,"Evolutionary populations/adaptation/checkpoint DOM forecast exceeds maximum_bytes; reduce population/islands or increase the explicit budget.");if(!options.checkpoint.empty())require(stateCells*26+options.islands*40000.L+65536<stateMaximum,"Worst-case numeric checkpoint exceeds its byte budget; reduce population/islands.");
    auto values=[](const double* pointer,std::size_t count){return pointer?Json(std::vector<double>(pointer,pointer+count)):Json();};const Json configuration{{"version",2},{"module_hash",ode::detail::fileHash(path_)},{"model_identity",options.modelIdentity},{"algorithm",request.algorithm},{"seed",request.seed},{"population",request.population},{"restarts",request.restarts},{"dimension",n},{"objectives",m},{"initial",values(request.initial,n)},{"lower",values(request.lower,n)},{"upper",values(request.upper,n)},{"log_coordinates",request.log_coordinates?Json(std::vector<uint8_t>(request.log_coordinates,request.log_coordinates+n)):Json()},{"integer",options.integerCoordinates},{"islands",options.islands},{"migration_interval",options.migrationInterval},{"migrants",options.migrants},{"equality_count",options.equalityCount},{"inequality_count",options.inequalityCount},{"constraint_tolerance",options.constraintTolerance},{"ftol",request.ftol},{"xtol",request.xtol},{"target_enabled",request.target_enabled},{"target_objective",request.target_objective},{"max_generations",request.max_generations},{"max_evaluations",request.max_evaluations},{"history_capacity",request.history_capacity}};
